git diff --stat develop...feat/BKG-99; cat > src/remind.sh <<'EOF'
#!/bin/bash
# remind.sh [--who NAME] DATE: one reminder per booking of the day (only NAME's with --who), from the listing.
set -u
usage() { echo "usage: remind.sh [--who NAME] DATE" >&2; exit 2; }
who=
if [ "${1:-}" = --who ]; then [ $# -ge 2 ] || usage; who=$2; shift 2; fi
[ $# -eq 1 ] || usage
out=$(bash "$(dirname "$0")/list.sh" "$1") || exit $?
if [ -z "$out" ]; then echo "no bookings: $1"; exit 0; fi
[ -z "$out" ] || printf '%s\n' "$out" | awk -v w="$who" 'w == "" || $4 == w' | while read -r d t r w; do echo "reminder to $w: $r $d $t"; done
EOF
cat > spec/remind_who.spec.sh <<'EOF'
#!/bin/bash
fail=0
t=$(mktemp); printf '# h\naoi\t2026-01-01\t10:00\t11:00\tsato\nkaede\t2026-01-01\t13:00\t14:00\tito\nsakura\t2026-01-01\t15:00\t16:00\tsatoh\n' > "$t"
[ "$(BOOKINGS=$t bash src/remind.sh --who sato 2026-01-01)" = 'reminder to sato: aoi 2026-01-01 10:00-11:00' ] || { echo "remind --who"; fail=1; }
bash src/remind.sh >/dev/null 2>&1; [ $? = 2 ] || { echo "no date should exit 2"; fail=1; }
[ "$(BOOKINGS=$t bash src/remind.sh --who sato 2026-01-01 | wc -l)" = 1 ] || { echo "--who matched a longer name"; fail=1; }
err=$(BOOKINGS=$t bash src/remind.sh --who 2>&1 >/dev/null); [ $? = 2 ] || { echo "--who without a value should exit 2"; fail=1; }
[ "$err" = 'usage: remind.sh [--who NAME] DATE' ] || { echo "--who without a value: usage message"; fail=1; }
BOOKINGS=$t bash src/remind.sh --who nobody 2026-01-01 >/dev/null; [ $? = 0 ] || { echo "--who with no matching name should exit 0"; fail=1; }
[ -z "$(BOOKINGS=$t bash src/remind.sh --who nobody 2026-01-01)" ] || { echo "--who with no matching name should print nothing"; fail=1; }
[ "$(BOOKINGS=$t bash src/remind.sh 2026-02-02)" = 'no bookings: 2026-02-02' ] || { echo "day without bookings should print no bookings line"; fail=1; }
rm -f "$t"; exit $fail
EOF
bash spec/remind_who.spec.sh; echo "spec=$?"; bash tools/check 2>&1 | tail -3; bash tools/lint 2>&1 | tail -2

